import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [studentFeedback, setStudentFeedback] = useState({});

  const handleFeedbackChange = (key, value) => {
    setStudentFeedback((prevFeedback) => ({ ...prevFeedback, [key]: value }));
  };

  return (
    <FeedbackContext.Provider value={{ feedback: studentFeedback, handleFeedbackChange }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackProvider, FeedbackContext };
```
In this code, we create a `FeedbackContext` using the `createContext` hook, and a `FeedbackProvider` component that wraps the child components. The `FeedbackProvider` component manages the state of the student feedback using the `useState` hook, and provides two values to the child components: `feedback` (the current student feedback state) and `handleFeedbackChange` (a function to update the feedback state).

