```
// Import required modules
import { BaseApplicationCustomizer } from '@microsoft/sp-application-customizers-base';
import { SPComponentLoader } from '@microsoft/sp-loader';
import { ToolStrip } from '@microsoft/sp-webpart-base';

class GoogleTagManagerCustomizer extends BaseApplicationCustomizer<IStrings> {
  // GTM container ID (replace with your own ID)
  private static readonly gtmContainerId: string = 'GTM-XXXXX';

  onInit(): Promise<void> {
    // Get the current page context
    const pageContext = SPComponentLoader.getComponentContext().globalContext.pageContext;

    // Add the GTM script tag to the page header
    const scriptTag = document.createElement('script');
    scriptTag.src = `https://www.googletagmanager.com/gtag/js?id=${GoogleTagManagerCustomizer.gtmContainerId}`;
    scriptTag.defer = true;
    document.getElementsByTagName('head')[0].appendChild(scriptTag);

    // Add the GTM data layer script tag to the page footer
    const dataLayerScriptTag = document.createElement('script');
    dataLayerScriptTag.innerHTML = `
      window.dataLayer = window.dataLayer || [];
      function gtag() {
        window.dataLayer.push(arguments);
      }
    `;
    dataLayerScriptTag.defer = true;
    document.body.appendChild(dataLayerScriptTag);

    // Send a test event to GTM
    const testEvent = window.dataLayer.push({
      'event': 'test-event'
    });
    console.log(`Test event sent to GTM: ${testEvent}`);

    return Promise.resolve();
  }
}

// Define the customizer's settings
export interface IStrings {
  // No settings needed for this customizer
}

// Register the customizer
SPComponentLoader.load('my-spfx-toolparts', { url: 'https://example.com/my-spfx-toolparts_MASTER/definitions.json' });
GoogleTagManagerCustomizer.register(GoogleTagManagerCustomizer);
```
**Explanation:**

This customizer uses the `BaseApplicationCustomizer` class from the `@microsoft/sp-application-customizers-base` package. The `onInit` method is called when the customizer initializes, and it adds the necessary GTM script tags to the page.

The first script tag is a `src` attribute that points to the GTM snippet. The `defer` attribute is set to `true` so that the script is loaded asynchronously. The second script tag is a `innerHTML` attribute that defines the GTM data layer function. This function is used to send events to GTM.

Finally, the customizer sends a test event to GTM using the `window.dataLayer.push` method.

**Note:**

* Make sure to replace `GTM-XXXXX` with your own GTM container ID.
* This customizer assumes that you have already set up GTM in your SharePoint site.
* This customizer is just an example and may need to be modified to fit your specific use case.
