	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS snapshots
	describeSnaps, err := ec2Svc.DescribeSnapshots(&ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:   aws.String("status"),
			Values: []*string{aws.String("completed")},
			},
		},
	})
	if err != nil {
		return nil, err
	}

	var monthlySnapshots []*ec2.Snapshot
	var dailySnapshots []*ec2.Snapshot
	var weeklySnapshots []*ec2.Snapshot
	var yearlySnapshots []*ec2.Snapshot

	// Group snapshots by backup_type
	for _, snap := range describeSnaps.Snapshots {
		backupType := *snap.Tags」

		switch backupType {
		case "monthly":
			monthlySnapshots = append(monthlySnapshots, snap)
		case "daily":
			dailySnapshots = append(dailySnapshots, snap)
		case "weekly":
			weeklySnapshots = append(weeklySnapshots, snap)
		case "yearly":
			yearlySnapshots = append(yearlySnapshots, snap)
		}
	}

	// Delete excess snapshots
	shouldDeleteMonthly := len(monthlySnapshots) > 14
	shouldDeleteDaily := len(dailySnapshots) > 10
	shouldDeleteWeekly := len(weeklySnapshots) > 4

	if shouldDeleteMonthly {
		for _, snap := range monthlySnapshots[14:] {
			err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: &snap.SnapshotId,
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	if shouldDeleteDaily {
		for _, snap := range dailySnapshots[10:] {
			err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: &snap.SnapshotId,
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	if shouldDeleteWeekly {
		for _, snap := range weeklySnapshots[4:] {
			err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: &snap.SnapshotId,
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	// Keep only the last 1 yearly snapshot
	if len(yearlySnapshots) > 1 {
		yearlySnapshots = yearlySnapshots[:1]

		for _, snap := range yearlySnapshots[1:] {
			err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: &snap.SnapshotId,
			})
			if err != nil {
				log.Println(err)
			}
		}
	}

	return nil, nil
}

func main() {
