```Python
import pygame
import random
import sys

# Define some constants
WIDTH = 800
HEIGHT = 600
BLOCK_SIZE = 20
SPEED = 10

# Define some colors
GREEN = (0, 255, 0)
BLACK = (0, 0, 0)
RED = (255, 0, 0)

class Snake:
    def __init__(self):
        self.body = [(WIDTH // 2, HEIGHT // 2)]
        self.direction = "right"

    def move(self):
        head = self.body[0]
        if self.direction == "right":
            new_head = (head[0] + BLOCK_SIZE, head[1])
        elif self.direction == "left":
            new_head = (head[0] - BLOCK_SIZE, head[1])
        elif self.direction == "up":
            new_head = (head[0], head[1] - BLOCK_SIZE)
        elif self.direction == "down":
            new_head = (head[0], head[1] + BLOCK_SIZE)

        self.body.insert(0, new_head)

        if new_head in self.body[1:]:
            return False
        else:
            self.body.pop()
            return True

    def change_direction(self, direction):
        if direction == "right" and self.direction != "left":
            self.direction = "right"
        elif direction == "left" and self.direction != "right":
            self.direction = "left"
        elif direction == "up" and self.direction != "down":
            self.direction = "up"
        elif direction == "down" and self.direction != "up":
            self.direction = "down"

class Game:
    def __init__(self):
        self.snake = Snake()
        self.apple = None
        self.score = 0

    def start(self):
        self.apple = (random.randint(0, WIDTH - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE,
                      random.randint(0, HEIGHT - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE)

        while True:
            pygame.init()
            screen = pygame.display.set_mode((WIDTH, HEIGHT))
            pygame.display.set_caption("Snake")
            clock = pygame.time.Clock()

            running = True
            while running:
                for event in pygame.event.get():
                    if event.type == pygame.QUIT:
                        running = False
                    elif event.type == pygame.KEYDOWN:
                        if event.key == pygame.K_SPACE:
                            self.snake = Snake()
                            self.score = 0
                            self.apple = (random.randint(0, WIDTH - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE,
                                          random.randint(0, HEIGHT - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE)
                        elif event.key == pygame.K_UP and self.snake.direction != "down":
                            self.snake.change_direction("up")
                        elif event.key == pygame.K_DOWN and self.snake.direction != "up":
                            self.snake.change_direction("down")
                        elif event.key == pygame.K_LEFT and self.snake.direction != "right":
                            self.snake.change_direction("left")
                        elif event.key == pygame.K_RIGHT and self.snake.direction != "left":
                            self.snake.change_direction("right")

                screen.fill(BLACK)
                for pos in self.snake.body:
                    pygame.draw.rect(screen, GREEN, (pos[0], pos[1], BLOCK_SIZE, BLOCK_SIZE))
                pygame.draw.rect(screen, RED, (self.apple[0], self.apple[1], BLOCK_SIZE, BLOCK_SIZE))

                if not self.snake.move():
                    running = False
                elif self.snake.body[0] == self.apple:
                    self.score += 1
                    self.snake.body.append(self.snake.body[-1])
                    self.apple = (random.randint(0, WIDTH - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE,
                                  random.randint(0, HEIGHT - BLOCK_SIZE) // BLOCK_SIZE * BLOCK_SIZE)

                pygame.display.update()
                clock.tick(SPEED)

            pygame.quit()
            sys.exit()

if __name__ == "__main__":
    game = Game()
    game.start()
```

