#include <pigpio.h>

#define PIN 12 // GPIO pin 12

int main() {
  // Initialize the pigpio library
  if (gpioInitialise() < 0) {
    std::cerr << "pigpio initialisation failed" << std::endl;
    return 1;
  }

  // Set GPIO pin 12 as an output
  gpioSetup(PIN, GPIO_OUTPUT);

  // Set GPIO pin 12 to low (0V)
  gpioWrite(PIN, GPIO_LOW);

  // Wait for 1 second
  delay(1000);

  // Set GPIO pin 12 to high (3.3V)
  gpioWrite(PIN, GPIO_HIGH);

  // Wait for 1 second
  delay(1000);

  // Clean up
  gpioTerminate();

  return 0;
}
